    if not isinstance(manifest['batch_id'],str)or not re.fullmatch(r'[a-z0-9_-]{1,32}',manifest['batch_id']):raise ValueError('batch identity')
    if not isinstance(manifest['events'],list)or len(manifest['events'])>64 or not isinstance(manifest['queries'],list)or len(manifest['queries'])>8 or not(manifest['events']or manifest['queries']):raise ValueError('batch budget')
    for kind,fields in [('events',{'event_id','member','lon','lat','stamp'}),('queries',{'query_id','lon','lat','radius_m','now','max_age','limit'})]:
        seen=set();identity='event_id'if kind=='events'else'query_id'
