            if not isinstance(row,dict)or set(row)!=fields:raise ValueError('entry schema')
            if not isinstance(row[identity],str)or not 1<=len(row[identity].encode())<=128 or row[identity]in seen:raise ValueError('entry identity')
            seen.add(row[identity])
