    old=command('HGET',managed[3],manifest['batch_id'])
    epoch=command('HGET',managed[2],'epoch')
    if epoch is not None and(not re.fullmatch(r'0|[1-9][0-9]*',epoch)or int(epoch)>1000000000):raise ValueError('epoch budget')
