    for event in manifest['events']:
        known=command('HGET',managed[4],event['event_id'])
        if known is not None and record(known)['input_sha256']!=digest(event):raise ValueError('event identity conflict')
        raw=command('HGET',managed[1],event['member'])
        if raw is not None and(not re.fullmatch(r'0|[1-9][0-9]*',raw)or int(raw)>2**53-1):raise ValueError('invalid existing timestamp')
        if event['member']not in versions:versions[event['member']]=None if raw is None else int(raw)
        if known is None and(versions[event['member']]is None or versions[event['member']]<event['stamp']):
